64	// Auth still works via OPENAI_API_KEY env var or symlinked auth.json.
65	//
66	// The directory lives under the user's home (not the system temp dir) because
67	// recent Codex versions refuse to install PATH helper binaries when CODEX_HOME
68	// sits under /tmp, which breaks subsequent tool calls.
69	func codexHome() (string, func(), error) {
70		home, err := os.UserHomeDir()
71		if err != nil {
72			return "", nil, fmt.Errorf("resolve user home dir: %w", err)
73		}
