199		_ = ctx
200		name := fmt.Sprintf("codex-resume-%d", time.Now().UnixNano())
201	
202		s, err := c.startTmuxSession(name, dir, home, "codex", "--dangerously-bypass-approvals-and-sandbox", "resume", sessionID)
203		if err != nil {
204			return nil, err
205		}
206	
207		// Dismiss any startup prompts until the input prompt appears.
208		for range 5 {
209			content, waitErr := s.WaitFor(c.PromptPattern(), 15*time.Second)
210			if waitErr != nil {
211				_ = s.Close()
212				return nil, fmt.Errorf("waiting for codex resumed prompt: %w", waitErr)
213			}
214			if !strings.Contains(content, "press enter to confirm") &&
215				!strings.Contains(content, "Use ↑/↓ to move") {
216				break
217			}
