230	// seedCodexHome writes trust + feature flag config and links auth credentials
231	// so Codex loads the project's .codex/ layer and can authenticate.
232	func seedCodexHome(home, projectDir string) error {
233		if err := os.MkdirAll(home, 0o750); err != nil {
234			return err
235		}
236	
237		// Write config with trust, feature flag, and pinned model to skip upgrade dialogs.
238		model := os.Getenv("E2E_CODEX_MODEL")
239		if model == "" {
240			model = "gpt-5.4"
241		}
242		config := fmt.Sprintf("model = %q\n\n[features]\ncodex_hooks = true\n\n[projects.%q]\ntrust_level = \"trusted\"\n", model, projectDir)
243		if err := os.WriteFile(filepath.Join(home, "config.toml"), []byte(config), 0o600); err != nil {
244			return err
245		}
246	
247		if apiKey := os.Getenv("OPENAI_API_KEY"); apiKey != "" {
248			return writeCodexAPIKeyAuth(home, apiKey)
249		}
250	
251		// Symlink auth.json from the real ~/.codex/ so API credentials are available.
252		if realHome, err := os.UserHomeDir(); err == nil {
253			src := filepath.Join(realHome, ".codex", "auth.json")
254			if _, err := os.Stat(src); err == nil {
255				_ = os.Symlink(src, filepath.Join(home, "auth.json"))
256			}
257		}
258	
259		return nil
260	}
261	
262	func writeCodexAPIKeyAuth(home, apiKey string) error {
263		auth := struct {
264			AuthMode     string `json:"auth_mode"`
265			OpenAIAPIKey string `json:"OPENAI_API_KEY"`
266		}{
267			AuthMode:     "apikey",
268			OpenAIAPIKey: apiKey,
269		}
270	
271		data, err := json.MarshalIndent(auth, "", "  ")
272		if err != nil {
273			return fmt.Errorf("marshal codex auth: %w", err)
274		}
275		data = append(data, '\n')
276	
277		if err := os.WriteFile(filepath.Join(home, "auth.json"), data, 0o600); err != nil {
278			return fmt.Errorf("write codex auth: %w", err)
279		}
280	
281		return nil
282	}
